Sub 'PrintFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'USUUSUARIO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &usuUsuario1.FromString(&GridStateDynamicFilter.Value) If not &usuUsuario1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterusuUsuarioDescription = format('%1 (%2)', "Usuário", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &FilterusuUsuarioDescription = format('%1 (%2)', "Usuário", "WWP_FilterContains") EndCase &usuUsuario = &usuUsuario1 print printBlockFilterusuUsuario EndIf Case &DynamicFiltersSelector1 = !'USUNOME' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &usuNome1.FromString(&GridStateDynamicFilter.Value) If not &usuNome1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterusuNomeDescription = format('%1 (%2)', "Nome", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &FilterusuNomeDescription = format('%1 (%2)', "Nome", "WWP_FilterContains") EndCase &usuNome = &usuNome1 print printBlockFilterusuNome EndIf Case &DynamicFiltersSelector1 = !'USUGUID' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &usuGUID1.FromString(&GridStateDynamicFilter.Value) If not &usuGUID1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterusuGUIDDescription = format('%1 (%2)', "Usuário GAM", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &FilterusuGUIDDescription = format('%1 (%2)', "Usuário GAM", "WWP_FilterContains") EndCase &usuGUID = &usuGUID1 print printBlockFilterusuGUID EndIf Case &DynamicFiltersSelector1 = !'USUEMAIL' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &usuEmail1.FromString(&GridStateDynamicFilter.Value) If not &usuEmail1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterusuEmailDescription = format('%1 (%2)', "Email", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &FilterusuEmailDescription = format('%1 (%2)', "Email", "WWP_FilterContains") EndCase &usuEmail = &usuEmail1 print printBlockFilterusuEmail EndIf Case &DynamicFiltersSelector1 = !'PREFCODIGO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &prefCodigo1.FromString(&GridStateDynamicFilter.Value) If not &prefCodigo1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterprefCodigoDescription = format('%1 (%2)', "Prefeitura", "=") EndCase &prefCodigo = &prefCodigo1 print printBlockFilterprefCodigo EndIf EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'USUUSUARIO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &usuUsuario2.FromString(&GridStateDynamicFilter.Value) If not &usuUsuario2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterusuUsuarioDescription = format('%1 (%2)', "Usuário", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &FilterusuUsuarioDescription = format('%1 (%2)', "Usuário", "WWP_FilterContains") EndCase &usuUsuario = &usuUsuario2 print printBlockFilterusuUsuario EndIf Case &DynamicFiltersSelector2 = !'USUNOME' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &usuNome2.FromString(&GridStateDynamicFilter.Value) If not &usuNome2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterusuNomeDescription = format('%1 (%2)', "Nome", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &FilterusuNomeDescription = format('%1 (%2)', "Nome", "WWP_FilterContains") EndCase &usuNome = &usuNome2 print printBlockFilterusuNome EndIf Case &DynamicFiltersSelector2 = !'USUGUID' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &usuGUID2.FromString(&GridStateDynamicFilter.Value) If not &usuGUID2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterusuGUIDDescription = format('%1 (%2)', "Usuário GAM", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &FilterusuGUIDDescription = format('%1 (%2)', "Usuário GAM", "WWP_FilterContains") EndCase &usuGUID = &usuGUID2 print printBlockFilterusuGUID EndIf Case &DynamicFiltersSelector2 = !'USUEMAIL' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &usuEmail2.FromString(&GridStateDynamicFilter.Value) If not &usuEmail2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterusuEmailDescription = format('%1 (%2)', "Email", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &FilterusuEmailDescription = format('%1 (%2)', "Email", "WWP_FilterContains") EndCase &usuEmail = &usuEmail2 print printBlockFilterusuEmail EndIf Case &DynamicFiltersSelector2 = !'PREFCODIGO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &prefCodigo2.FromString(&GridStateDynamicFilter.Value) If not &prefCodigo2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterprefCodigoDescription = format('%1 (%2)', "Prefeitura", "=") EndCase &prefCodigo = &prefCodigo2 print printBlockFilterprefCodigo EndIf EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'USUUSUARIO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &usuUsuario3.FromString(&GridStateDynamicFilter.Value) If not &usuUsuario3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterusuUsuarioDescription = format('%1 (%2)', "Usuário", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &FilterusuUsuarioDescription = format('%1 (%2)', "Usuário", "WWP_FilterContains") EndCase &usuUsuario = &usuUsuario3 print printBlockFilterusuUsuario EndIf Case &DynamicFiltersSelector3 = !'USUNOME' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &usuNome3.FromString(&GridStateDynamicFilter.Value) If not &usuNome3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterusuNomeDescription = format('%1 (%2)', "Nome", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &FilterusuNomeDescription = format('%1 (%2)', "Nome", "WWP_FilterContains") EndCase &usuNome = &usuNome3 print printBlockFilterusuNome EndIf Case &DynamicFiltersSelector3 = !'USUGUID' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &usuGUID3.FromString(&GridStateDynamicFilter.Value) If not &usuGUID3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterusuGUIDDescription = format('%1 (%2)', "Usuário GAM", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &FilterusuGUIDDescription = format('%1 (%2)', "Usuário GAM", "WWP_FilterContains") EndCase &usuGUID = &usuGUID3 print printBlockFilterusuGUID EndIf Case &DynamicFiltersSelector3 = !'USUEMAIL' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &usuEmail3.FromString(&GridStateDynamicFilter.Value) If not &usuEmail3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterusuEmailDescription = format('%1 (%2)', "Email", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &FilterusuEmailDescription = format('%1 (%2)', "Email", "WWP_FilterContains") EndCase &usuEmail = &usuEmail3 print printBlockFilterusuEmail EndIf Case &DynamicFiltersSelector3 = !'PREFCODIGO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &prefCodigo3.FromString(&GridStateDynamicFilter.Value) If not &prefCodigo3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterprefCodigoDescription = format('%1 (%2)', "Prefeitura", "=") EndCase &prefCodigo = &prefCodigo3 print printBlockFilterprefCodigo EndIf EndCase EndIf EndIf EndIf If not (&TFusuCodigo.IsEmpty() AND &TFusuCodigo_To.IsEmpty()) print printBlockTFusuCodigo &TFusuCodigo_To_Description = format('%1 (%2)', "Código", "WWP_TSTo") print printBlockTFusuCodigo_To EndIf If not (&TFprefCodigo.IsEmpty() AND &TFprefCodigo_To.IsEmpty()) print printBlockTFprefCodigo &TFprefCodigo_To_Description = format('%1 (%2)', "Prefeitura", "WWP_TSTo") print printBlockTFprefCodigo_To EndIf If not &TFusuUsuario_Sel.IsEmpty() print printBlockTFusuUsuario_Sel Else If not &TFusuUsuario.IsEmpty() print printBlockTFusuUsuario EndIf EndIf If not &TFusuNome_Sel.IsEmpty() print printBlockTFusuNome_Sel Else If not &TFusuNome.IsEmpty() print printBlockTFusuNome EndIf EndIf If not (&TFusuCargo.IsEmpty() AND &TFusuCargo_To.IsEmpty()) print printBlockTFusuCargo &TFusuCargo_To_Description = format('%1 (%2)', "Cargo", "WWP_TSTo") print printBlockTFusuCargo_To EndIf If not &TFusuEmail_Sel.IsEmpty() print printBlockTFusuEmail_Sel Else If not &TFusuEmail.IsEmpty() print printBlockTFusuEmail EndIf EndIf &TFusuStatus_Sels.FromJson(&TFusuStatus_SelsJson) If not &TFusuStatus_Sels.Count = 0 &i = 1 For &TFusuStatus_Sel in &TFusuStatus_Sels If &i = 1 &TFusuStatus_SelDscs = '' Else &TFusuStatus_SelDscs += ', ' EndIf &FilterTFusuStatus_SelValueDescription = '' Do Case Case &TFusuStatus_Sel.ToString().Trim() = !"A" &FilterTFusuStatus_SelValueDescription = "Ativo"
Case &TFusuStatus_Sel.ToString().Trim() = !"I" &FilterTFusuStatus_SelValueDescription = "Inativo"
EndCase
&TFusuStatus_SelDscs += &FilterTFusuStatus_SelValueDescription &i += 1 EndFor print printBlockTFusuStatus_Sel EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
print printBlockBeforeGrid print printBlockLines_titles
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each trnsusuarios order usuUsuario when &OrderedBy = 1 AND &OrderedDsc = False order (usuUsuario) when &OrderedBy = 1 AND &OrderedDsc = True order usuCodigo when &OrderedBy = 2 AND &OrderedDsc = False order (usuCodigo) when &OrderedBy = 2 AND &OrderedDsc = True order prefCodigo when &OrderedBy = 3 AND &OrderedDsc = False order (prefCodigo) when &OrderedBy = 3 AND &OrderedDsc = True order usuNome when &OrderedBy = 4 AND &OrderedDsc = False order (usuNome) when &OrderedBy = 4 AND &OrderedDsc = True order usuCargo when &OrderedBy = 5 AND &OrderedDsc = False order (usuCargo) when &OrderedBy = 5 AND &OrderedDsc = True order usuEmail when &OrderedBy = 6 AND &OrderedDsc = False order (usuEmail) when &OrderedBy = 6 AND &OrderedDsc = True order usuStatus when &OrderedBy = 7 AND &OrderedDsc = False order (usuStatus) when &OrderedBy = 7 AND &OrderedDsc = True
using trnsusuariosWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &usuUsuario1, &usuNome1, &usuGUID1, &usuEmail1 , &prefCodigo1, &DynamicFiltersEnabled2, &DynamicFiltersSelector2, &DynamicFiltersOperator2, &usuUsuario2, &usuNome2 , &usuGUID2, &usuEmail2, &prefCodigo2, &DynamicFiltersEnabled3, &DynamicFiltersSelector3, &DynamicFiltersOperator3 , &usuUsuario3, &usuNome3, &usuGUID3, &usuEmail3, &prefCodigo3, &TFusuCodigo , &TFusuCodigo_To, &TFprefCodigo, &TFprefCodigo_To, &TFusuUsuario, &TFusuUsuario_Sel, &TFusuNome , &TFusuNome_Sel, &TFusuCargo, &TFusuCargo_To, &TFusuEmail, &TFusuEmail_Sel, &TFusuStatus_Sels) &usuStatusDescription = '' Do Case Case usuStatus.ToString().Trim() = !"A" &usuStatusDescription = "Ativo"
Case usuStatus.ToString().Trim() = !"I" &usuStatusDescription = "Inativo"
EndCase
Do 'BeforePrintLine' print printBlockLines_data Do 'AfterPrintLine' EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnsusuariosWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnsusuariosWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnsusuariosWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFUSUCODIGO" &TFusuCodigo.FromString(&GridStateFilterValue.Value) &TFusuCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFPREFCODIGO" &TFprefCodigo.FromString(&GridStateFilterValue.Value) &TFprefCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFUSUUSUARIO" &TFusuUsuario.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFUSUUSUARIO_SEL" &TFusuUsuario_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFUSUNOME" &TFusuNome.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFUSUNOME_SEL" &TFusuNome_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFUSUCARGO" &TFusuCargo.FromString(&GridStateFilterValue.Value) &TFusuCargo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFUSUEMAIL" &TFusuEmail.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFUSUEMAIL_SEL" &TFusuEmail_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFUSUSTATUS_SEL" &TFusuStatus_SelsJson = &GridStateFilterValue.Value &TFusuStatus_Sels.FromJson(&TFusuStatus_SelsJson) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
